"""Source fixtures prove generated byte identity, not executable qualification."""

import os
import subprocess
from dataclasses import replace
from pathlib import Path

import pytest
from capsem_builder.gate import config as gate_config
from capsem_builder.release.tools import preinstall_resource as resource

ROOT = Path(__file__).resolve().parents[3]


def elf(machine: int = 183) -> bytes:
    # An explicitly non-executable ELF-header source double. Never run it.
    header = bytearray(64)
    header[:7] = b"\x7fELF\x02\x01\x01"
    header[16:20] = b"\x03\x00" + machine.to_bytes(2, "little")
    return bytes(header) + b"source-format-double\n" * 100


@pytest.fixture
def package(tmp_path: Path) -> Path:
    (tmp_path / "DEBIAN").mkdir()
    (tmp_path / "DEBIAN/control").write_text("Package: source-fixture\nArchitecture: arm64\n")
    (tmp_path / "DEBIAN/preinst").write_text("#!/bin/bash\nprintf 'original body\\n'\n")
    binary = tmp_path / "usr/bin/capsem-ledger"
    binary.parent.mkdir(parents=True)
    binary.write_bytes(elf())
    binary.chmod(0o755)
    return tmp_path


def test_generated_resource_matches_the_stripped_payload_and_keeps_original_body(package: Path) -> None:
    limits = resource.load_limits(ROOT)
    resource.embed(package, repository=ROOT, limits=limits)
    generated = (package / "DEBIAN/preinst").read_bytes()
    assert generated.startswith(b"#!/bin/bash\n")
    assert generated.endswith(b"printf 'original body\\n'\n")
    assert b"--preinstall-ledger-admission" in generated
    assert b"--target-user" in generated
    assert b"/usr/sbin/runuser" in generated
    assert b"/usr/bin/timeout" in generated
    resource.verify(package, repository=ROOT, limits=limits)
    binary = package / "usr/bin/capsem-ledger"
    binary.write_bytes(elf() + b"changed after embedding")
    with pytest.raises(ValueError, match="identity"):
        resource.verify(package, repository=ROOT, limits=limits)


@pytest.mark.parametrize("member", ["usr/bin/capsem-ledger", "DEBIAN/preinst", "DEBIAN/control"])
def test_resource_rejects_symlinks(package: Path, tmp_path: Path, member: str) -> None:
    path = package / member
    foreign = tmp_path / "foreign"
    path.rename(foreign)
    path.symlink_to(foreign)
    with pytest.raises(ValueError, match="regular"):
        resource.embed(package, repository=ROOT, limits=resource.load_limits(ROOT))


@pytest.mark.parametrize(
    "data",
    [b"#!/bin/sh\nexit 0\n", b"\x7fELF", elf(62), b"\xcf\xfa\xed\xfe" + bytes(64)],
)
def test_resource_rejects_nonmatching_target_bytes(package: Path, data: bytes) -> None:
    (package / "usr/bin/capsem-ledger").write_bytes(data)
    with pytest.raises(ValueError, match=r"ELF|architecture"):
        resource.embed(package, repository=ROOT, limits=resource.load_limits(ROOT))


@pytest.mark.parametrize("field", ["max_binary_bytes", "max_encoded_bytes", "max_script_bytes"])
def test_each_budget_refuses_without_changing_original_preinst(package: Path, field: str) -> None:
    original = (package / "DEBIAN/preinst").read_bytes()
    limits = replace(resource.load_limits(ROOT), **{field: 1})
    with pytest.raises(ValueError, match="budget"):
        resource.embed(package, repository=ROOT, limits=limits)
    assert (package / "DEBIAN/preinst").read_bytes() == original


def test_resource_rejects_reembedding_and_truncated_control(package: Path) -> None:
    limits = resource.load_limits(ROOT)
    resource.embed(package, repository=ROOT, limits=limits)
    with pytest.raises(ValueError, match="already"):
        resource.embed(package, repository=ROOT, limits=limits)
    script = package / "DEBIAN/preinst"
    script.write_bytes(script.read_bytes()[:-40])
    with pytest.raises(ValueError, match=r"identity|body"):
        resource.verify(package, repository=ROOT, limits=limits)


@pytest.mark.parametrize("value", [b"", b"x" * 2048])
def test_control_stream_is_bounded_and_not_empty(value: bytes) -> None:
    import io

    with pytest.raises(ValueError, match="control"):
        resource.check_control(io.BytesIO(value), maximum=1024)


def test_control_stream_is_counted_without_materializing_it() -> None:
    import io

    assert resource.check_control(io.BytesIO(bytes(2048)), maximum=4096) == 2048


def test_gate_and_stdlib_packaging_read_the_same_config_owner() -> None:
    assert vars(resource.load_limits(ROOT)) == gate_config.load(ROOT).package.preinstall_resource.model_dump()


def test_generated_base64_decodes_exact_original_bytes_without_execution(package: Path) -> None:
    resource.embed(package, repository=ROOT, limits=resource.load_limits(ROOT))
    script = (package / "DEBIAN/preinst").read_bytes().split(resource.END)[0]
    result = subprocess.run(
        ["bash"], input=script + b"\ncapsem_write_preinstall_resource\n",
        capture_output=True, timeout=10,
    )
    assert result.returncode == 0, result.stderr
    assert result.stdout == (package / "usr/bin/capsem-ledger").read_bytes()


@pytest.mark.parametrize("mode", [0, 0o644, 0o4644, 0o2644, 0o4755, 0o2755, 0o6755])
def test_resource_rejects_nonexecutable_or_setid_mode(mode: int) -> None:
    with pytest.raises(ValueError, match="executable without set-id authority"):
        resource.require_executable_mode(mode)


@pytest.mark.parametrize("mode", [0o111, 0o500, 0o755, 0o555, 0o1755, 0o100755])
def test_resource_accepts_unprivileged_executable_mode(mode: int) -> None:
    resource.require_executable_mode(mode)


def test_candidate_rejects_nonexecutable_mode(package: Path) -> None:
    binary = package / "usr/bin/capsem-ledger"
    binary.chmod(0o644)
    with pytest.raises(ValueError, match="executable"):
        resource.embed(package, repository=ROOT, limits=resource.load_limits(ROOT))


@pytest.mark.parametrize("architecture", ["all", "riscv64", "arm64\nArchitecture: amd64"])
def test_candidate_rejects_unsupported_or_duplicate_architecture(package: Path, architecture: str) -> None:
    (package / "DEBIAN/control").write_text(f"Architecture: {architecture}\n")
    with pytest.raises(ValueError, match="architecture"):
        resource.embed(package, repository=ROOT, limits=resource.load_limits(ROOT))


def test_candidate_rejects_parent_symlink_and_shared_payload(package: Path) -> None:
    binary = package / "usr/bin/capsem-ledger"
    os.link(binary, package / "foreign-link")
    with pytest.raises(ValueError, match="unshared"):
        resource.embed(package, repository=ROOT, limits=resource.load_limits(ROOT))
    (package / "foreign-link").unlink()
    (package / "usr/bin").rename(package / "original-bin")
    (package / "usr/bin").symlink_to(package / "original-bin", target_is_directory=True)
    with pytest.raises(ValueError, match="directories"):
        resource.embed(package, repository=ROOT, limits=resource.load_limits(ROOT))


def test_tampered_encoded_resource_refused_before_packaging(package: Path) -> None:
    limits = resource.load_limits(ROOT)
    resource.embed(package, repository=ROOT, limits=limits)
    script = package / "DEBIAN/preinst"
    value = script.read_bytes()
    encoded = resource.base64.encodebytes(elf())
    script.write_bytes(value.replace(encoded, b"A" + encoded[1:], 1))
    with pytest.raises(ValueError, match="identity"):
        resource.verify(package, repository=ROOT, limits=limits)


def test_supported_amd64_payload_uses_its_actual_declared_machine(package: Path) -> None:
    (package / "DEBIAN/control").write_text("Architecture: amd64\n")
    (package / "usr/bin/capsem-ledger").write_bytes(elf(62))
    limits = resource.load_limits(ROOT)
    resource.embed(package, repository=ROOT, limits=limits)
    resource.verify(package, repository=ROOT, limits=limits)


def test_failed_atomic_publication_cleans_only_own_temporary_and_preserves_script(
    package: Path, monkeypatch: pytest.MonkeyPatch,
) -> None:
    original = (package / "DEBIAN/preinst").read_bytes()
    members = set((package / "DEBIAN").iterdir())

    def refuse(*args: object) -> None:
        raise OSError("publication refused")

    monkeypatch.setattr(resource.os, "replace", refuse)
    with pytest.raises(OSError, match="publication refused"):
        resource.embed(package, repository=ROOT, limits=resource.load_limits(ROOT))
    assert (package / "DEBIAN/preinst").read_bytes() == original
    assert set((package / "DEBIAN").iterdir()) == members


def test_generated_linux_binding_forwards_only_the_extra_restriction(package: Path) -> None:
    resource.embed(package, repository=ROOT, limits=resource.load_limits(ROOT))
    prefix = (package / "DEBIAN/preinst").read_bytes().split(resource.END)[0]
    result = subprocess.run(["bash"], input=prefix + b'\ncapsem_admit_preinstall_ledger() { printf "%s\\n" "$@"; }\ncapsem_run_preinstall_ledger_admission fixture-user --require-current-host\n', capture_output=True, timeout=10)
    assert result.returncode == 0, result.stderr
    lines = result.stdout.decode().splitlines()
    assert len(lines) == 6 and lines[0] == "fixture-user" and lines[-1] == "--require-current-host"
